import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class FastDateFormat_format_TriageGen0Test {

    @Test
    public void testFormatWithStandardPattern() {
        // Test default instance (pattern is usually yyyy-MM-dd HH:mm:ss Z or similar depending on implementation details)
        // But we use getInstance(String) to ensure a predictable pattern for the test
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Date date = new Date(1609459200000L); // 2021-01-01 00:00:00 UTC

        String result = fdf.format(date);
        assertNotNull(result);
        assertEquals("2021-01-01", result);
    }

    @Test
    public void testFormatWithTimeZone() {
        // Test with specific TimeZone (GMT+8)
        TimeZone tz = TimeZone.getTimeZone("GMT+8");
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd HH:mm:ss", tz);

        // 2021-01-01 00:00:00 UTC is 2021-01-01 08:00:00 GMT+8
        Date date = new Date(1609459200000L); 

        String result = fdf.format(date);
        assertEquals("2021-01-01 08:00:00", result);
    }

    @Test
    public void testFormatWithLocale() {
        // Test with specific Locale to ensure pattern components (like month names) are respected
        // Note: pattern "MMMM" produces full month name
        FastDateFormat fdf = FastDateFormat.getInstance("MMMM", Locale.FRENCH);

        // Jan 1st 2021
        Date date = new Date(1609459200000L);

        String result = fdf.format(date);
        // In French, January is "janvier"
        assertEquals("janvier", result.toLowerCase());
    }

    @Test
    public void testFormatWithDateTimeInstance() {
        // Test using the predefined style instances
        FastDateFormat fdf = FastDateFormat.getDateTimeInstance(Calendar.SHORT, Calendar.SHORT, Locale.US, TimeZone.getTimeZone("UTC"));
        Date date = new Date(1609459200000L);

        String result = fdf.format(date);
        // Expected format for SHORT/SHORT in US is typically M/d/yy h:mm a
        // 1/1/21 12:00 AM (or similar depending on JDK version)
        assertNotNull(result);
        // Since exact string depends on JDK version, we verify it's not empty and matches general pattern
        assertEquals(true, result.length() > 0);
    }

    @Test
    public void testFormatWithEdgeCaseDate() {
        // Test with Epoch
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy");
        Date epoch = new Date(0);
        assertEquals("1970", fdf.format(epoch));
    }

    @Test
    public void testFormatWithLongMillis() {
        // The class provides an overload for long, verifying consistency with the Date version
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        long millis = 1609459200000L;

        String resultFromLong = fdf.format(millis);
        String resultFromDate = fdf.format(new Date(millis));

        assertEquals(resultFromLong, resultFromDate);
    }

    @Test
    public void testFormatWithCalendar() {
        // The class provides an overload for Calendar
        FastDateFormat fdf = FastDateFormat.getInstance("yyyy-MM-dd");
        Calendar cal = Calendar.getInstance();
        cal.set(2021, Calendar.JANUARY, 1, 0, 0, 0);
        cal.set(Calendar.MILLISECOND, 0);

        String resultFromCal = fdf.format(cal.getTime());
        String resultFromCalendar = fdf.format(cal);

        assertEquals(resultFromCal, resultFromCalendar);
    }
}
